-- Scene Agent Studio Interpreter
-- Paste this file into a local Roblox Studio plugin. It intentionally accepts
-- only a complete session.json document generated by this project.

assert(plugin, "SceneInterpreter must run as a Roblox Studio plugin")

local ChangeHistoryService = game:GetService("ChangeHistoryService")
local HttpService = game:GetService("HttpService")
local Workspace = game:GetService("Workspace")

local PART_TYPES = {Ball = true, Block = true, Cylinder = true, Wedge = true, CornerWedge = true}
local JOINT_DEGREES_OF_FREEDOM = {fixed = 0, hinge = 1, universal = 2}
local EDITABLE = {
	name = true, shape = true, position = true, rotation = true, size = true, color = true,
	material = true, transparency = true, anchored = true, can_collide = true,
}

local function expect(condition, message)
	if not condition then error(message, 0) end
end

local function vec3(value, field)
	expect(type(value) == "table" and #value == 3, field .. " must be a three-number array")
	for _, number in ipairs(value) do expect(type(number) == "number", field .. " contains a non-number") end
	return Vector3.new(value[1], value[2], value[3])
end

local function color3(value)
	local color = vec3(value, "color")
	expect(color.X >= 0 and color.X <= 1 and color.Y >= 0 and color.Y <= 1 and color.Z >= 0 and color.Z <= 1,
		"color must use RGB values from 0 through 1")
	return Color3.new(color.X, color.Y, color.Z)
end

local function setProperties(part, properties)
	expect(type(properties) == "table", "properties must be an object")
	for property, value in pairs(properties) do
		expect(EDITABLE[property], "unsupported property: " .. tostring(property))
		if property == "name" then
			expect(type(value) == "string" and #value > 0, "name must be a non-empty string")
			part.Name = value
		elseif property == "shape" then
			expect(PART_TYPES[value], "unsupported shape")
			part.Shape = Enum.PartType[value]
		elseif property == "position" then
			part.Position = vec3(value, "position")
		elseif property == "rotation" then
			local degrees = vec3(value, "rotation")
			part.CFrame = CFrame.new(part.Position) * CFrame.fromOrientation(
				math.rad(degrees.X), math.rad(degrees.Y), math.rad(degrees.Z)
			)
		elseif property == "size" then
			local size = vec3(value, "size")
			expect(size.X > 0 and size.Y > 0 and size.Z > 0, "size values must be positive")
			part.Size = size
		elseif property == "color" then
			part.Color = color3(value)
		elseif property == "material" then
			expect(type(value) == "string" and Enum.Material[value] ~= nil, "unsupported material")
			part.Material = Enum.Material[value]
		elseif property == "transparency" then
			expect(type(value) == "number" and value >= 0 and value <= 1, "transparency must be from 0 through 1")
			part.Transparency = value
		elseif property == "anchored" then
			expect(type(value) == "boolean", "anchored must be boolean")
			part.Anchored = value
		elseif property == "can_collide" then
			expect(type(value) == "boolean", "can_collide must be boolean")
			part.CanCollide = value
		end
	end
end

local function makePart(functionId, payload, rigged)
	expect(type(payload.name) == "string" and #payload.name > 0, "add_part requires a name")
	expect(PART_TYPES[payload.shape], "add_part uses unsupported shape")
	local part = Instance.new("Part")
	part.Name = payload.name
	part.Shape = Enum.PartType[payload.shape]
	part:SetAttribute("SceneAgentFunctionId", functionId)
	setProperties(part, {
		position = payload.position,
		rotation = payload.rotation or {0, 0, 0},
		size = payload.size,
		color = payload.color,
		material = payload.material or "Plastic",
		transparency = payload.transparency or 0,
		anchored = rigged and false or payload.anchored ~= false,
		can_collide = rigged and false or payload.can_collide ~= false,
	})
	return part
end

local function readJointMotion(payload)
	local motionType = payload.motion_type
	expect(type(motionType) == "string" and JOINT_DEGREES_OF_FREEDOM[motionType] ~= nil,
		"add_rig_part requires motion_type fixed, hinge, or universal")
	local degreesOfFreedom = JOINT_DEGREES_OF_FREEDOM[motionType]
	expect(type(payload.axes) == "table" and #payload.axes == degreesOfFreedom,
		"joint axes do not match motion_type")
	expect(type(payload.angle_ranges) == "table" and #payload.angle_ranges == degreesOfFreedom,
		"joint angle_ranges do not match motion_type")
	local axes, ranges = {}, {}
	for index = 1, degreesOfFreedom do
		local axis = vec3(payload.axes[index], "axes[" .. index .. "]")
		expect(axis.Magnitude > 0.000001, "joint axis must not be zero")
		axes[index] = axis.Unit
		local range = payload.angle_ranges[index]
		expect(type(range) == "table" and #range == 2 and type(range[1]) == "number" and type(range[2]) == "number",
			"each joint angle range must be [min,max]")
		expect(range[1] >= -180 and range[1] <= 180 and range[2] >= -180 and range[2] <= 180,
			"joint angles must be between -180 and 180")
		ranges[index] = range
	end
	if degreesOfFreedom == 2 then
		expect(math.abs(axes[1]:Dot(axes[2])) <= 0.95, "universal joint axes must not be parallel")
	end
	return motionType, axes, ranges
end

local function makeMotor6D(functionId, payload, parentPart, childPart)
	expect(type(payload.parent_part_id) == "string" and #payload.parent_part_id > 0,
		"add_rig_part requires parent_part_id")
	expect(type(payload.joint_name) == "string" and #payload.joint_name > 0,
		"add_rig_part requires joint_name")
	local jointPosition = vec3(payload.joint_position, "joint_position")
	local motionType, axes, ranges = readJointMotion(payload)
	local joint = Instance.new("Motor6D")
	joint.Name = payload.joint_name
	joint.Part0 = parentPart
	joint.Part1 = childPart
	joint.C0 = parentPart.CFrame:ToObjectSpace(CFrame.new(jointPosition))
	joint.C1 = childPart.CFrame:ToObjectSpace(CFrame.new(jointPosition))
	joint:SetAttribute("SceneAgentFunctionId", functionId)
	joint:SetAttribute("SceneAgentMotionType", motionType)
	for index, axis in ipairs(axes) do
		joint:SetAttribute("SceneAgentAxis" .. index, axis)
		joint:SetAttribute("SceneAgentRange" .. index .. "Min", ranges[index][1])
		joint:SetAttribute("SceneAgentRange" .. index .. "Max", ranges[index][2])
		joint:SetAttribute("SceneAgentRange" .. index .. "Wraps", ranges[index][1] > ranges[index][2])
	end
	joint.Parent = childPart
	return joint
end

local function rebuild(document)
	expect(type(document) == "table" and type(document.functions) == "table", "expected a session.json document with functions")
	local staging = Instance.new("Model")
	staging.Name = "GeneratedScene"
	staging:SetAttribute("SceneAgentTitle", tostring(document.title or "Untitled scene"))
	local partsByFunction = {}
	local applied = {}
	local rootPart = nil

	local ok, message = pcall(function()
		for index, entry in ipairs(document.functions) do
			expect(type(entry) == "table" and type(entry.id) == "string" and type(entry.op) == "string",
				"function " .. index .. " has no id or operation")
			if entry.active ~= false then
				for _, dependency in ipairs(entry.depends_on or {}) do
					expect(applied[dependency], "function " .. entry.id .. " has unavailable dependency " .. dependency)
				end
				if entry.op == "add_part" then
					local part = makePart(entry.id, entry.payload or {}, false)
					part.Parent = staging
					partsByFunction[entry.id] = part
					applied[entry.id] = true
				elseif entry.op == "add_rig_root" then
					expect(rootPart == nil, "a character rig can have only one active primary part")
					local part = makePart(entry.id, entry.payload or {}, true)
					part.Parent = staging
					partsByFunction[entry.id] = part
					rootPart = part
					applied[entry.id] = true
				elseif entry.op == "add_rig_part" then
					local payload = entry.payload or {}
					local parentPart = partsByFunction[payload.parent_part_id]
					expect(parentPart ~= nil, "rig part targets unavailable parent " .. tostring(payload.parent_part_id))
					local part = makePart(entry.id, payload, true)
					part.Parent = staging
					makeMotor6D(entry.id, payload, parentPart, part)
					partsByFunction[entry.id] = part
					applied[entry.id] = true
				elseif entry.op == "set_part_properties" then
					local payload = entry.payload or {}
					local part = partsByFunction[payload.target_id]
					expect(part ~= nil, "property edit targets unavailable part " .. tostring(payload.target_id))
					setProperties(part, payload.properties)
					applied[entry.id] = true
				else
					error("unsupported stored operation: " .. entry.op, 0)
				end
			end
		end
	end)
	if not ok then
		staging:Destroy()
		error(message, 0)
	end

	ChangeHistoryService:SetWaypoint("Scene Agent: before rebuild")
	local existing = Workspace:FindFirstChild("GeneratedScene")
	if existing then existing:Destroy() end
	if rootPart then staging.PrimaryPart = rootPart end
	staging.Parent = Workspace
	ChangeHistoryService:SetWaypoint("Scene Agent: rebuilt generated scene")
	return #staging:GetChildren()
end

-- UI: paste the complete Python session.json, then apply it into Workspace.
local toolbar = plugin:CreateToolbar("Scene Agent")
local toggleButton = toolbar:CreateButton("SceneInterpreter", "Open Scene Agent JSON interpreter", "", "Interpreter")
toggleButton.ClickableWhenViewportHidden = true
local widgetInfo = DockWidgetPluginGuiInfo.new(Enum.InitialDockState.Float, false, false, 520, 600, 360, 320)
local widget = plugin:CreateDockWidgetPluginGuiAsync("SceneAgentInterpreterV1", widgetInfo)
widget.Title = "Scene Agent Interpreter"

local input = Instance.new("TextBox")
input.Name = "SessionJson"
input.MultiLine = true
input.ClearTextOnFocus = false
input.TextXAlignment = Enum.TextXAlignment.Left
input.TextYAlignment = Enum.TextYAlignment.Top
input.TextWrapped = false
input.Font = Enum.Font.Code
input.TextSize = 14
input.PlaceholderText = "Paste the complete session.json exported by roblox_scene_agent"
input.Size = UDim2.new(1, -16, 1, -86)
input.Position = UDim2.fromOffset(8, 8)
input.Parent = widget

local applyButton = Instance.new("TextButton")
applyButton.Text = "Validate and rebuild GeneratedScene"
applyButton.Size = UDim2.new(1, -16, 0, 34)
applyButton.Position = UDim2.new(0, 8, 1, -70)
applyButton.Parent = widget

local status = Instance.new("TextLabel")
status.Text = "Paste a session.json document. Existing GeneratedScene is preserved on validation failure."
status.TextWrapped = true
status.TextXAlignment = Enum.TextXAlignment.Left
status.Size = UDim2.new(1, -16, 0, 30)
status.Position = UDim2.new(0, 8, 1, -34)
status.Parent = widget

toggleButton.Click:Connect(function() widget.Enabled = not widget.Enabled end)
applyButton.MouseButton1Click:Connect(function()
	local success, result = pcall(function()
		return rebuild(HttpService:JSONDecode(input.Text))
	end)
	if success then
		status.Text = "Applied " .. tostring(result) .. " parts to Workspace.GeneratedScene."
		status.TextColor3 = Color3.fromRGB(80, 200, 120)
	else
		status.Text = "Validation failed: " .. tostring(result)
		status.TextColor3 = Color3.fromRGB(240, 95, 95)
	end
end)
